function nextZIndex(){
return Math.max(0,...$$('.object').map(o=>Number(o.style.zIndex||0)))+1
}
function refreshKhmerDate(){
let value=khmerDateFor($('#date').value,$('#time').value);
$('#khmerDatePreview').textContent=value||'Khmer calendar conversion is unavailable. Check your connection and reload.';
return value
}
function syncFields(shouldSave=true){
const mode=$('#languageMode').value||'both';
const names=mode==='km'?($('#namesKm').value||$('#names').value):$('#names').value;
const message=mode==='km'?($('#messageKm').value||$('#message').value):$('#message').value;
const title=$('[data-id="title"] .content');
const subtitle=$('[data-id="subtitle"] .content');
if(title){
if(!state.objects?.title?.richText)title.textContent=names;
title.classList.toggle('khmer-text',mode==='km')
}
if(subtitle){
if(!state.objects?.subtitle?.richText)subtitle.textContent=message;
subtitle.classList.toggle('khmer-text',mode==='km')
}
let dt=new Date($('#date').value+'T00:00:00');
let label=isNaN(dt)?$('#date').value:dt.toLocaleDateString(undefined,{
day:'numeric',
month:'long',
year:'numeric'
}),
time=$('#time').value;
const details=$('[data-id="details"] .content');
const venueLabel=mode==='km'?($('#venueKm').value||$('#venue').value):$('#venue').value;
if(details){
if(!state.objects?.details?.richText)details.innerHTML=`${label}${time?` · ${time}`:''}<br>${venueLabel}`;
details.classList.toggle('khmer-text',mode==='km')
}
refreshKhmerDate();
if(shouldSave)save()
}
const eventFieldIds=new Set(['names','namesKm','date','time','venue','venueKm','message','messageKm']);
function commitEventFieldInput(event){
const target=event.target;
if(!(target instanceof HTMLInputElement||target instanceof HTMLTextAreaElement)||!eventFieldIds.has(target.id))return;
if(event.__einviteEventFieldHandled)return;
event.__einviteEventFieldHandled=true;
const id=target.id,value=target.value;
target.defaultValue=value;
state.fields||={};
state.fields[id]=value;
if(document.documentElement.dataset.editorReady==='true')recentFieldEdits.set(id,{value,at:Date.now()});
const finish=(attempt=0)=>{
const connected=document.getElementById(id);
if(!connected&&attempt<24)return setTimeout(()=>finish(attempt+1),25);
if(connected&&connected.value!==value)connected.value=value;
if(connected)connected.defaultValue=value;
if(document.getElementById('languageMode')&&document.getElementById('names')&&document.getElementById('date'))syncFields();
};
if(target.isConnected)finish();else setTimeout(()=>finish(),0);
}
function bindEventFieldInputs(root=document){
for(const id of eventFieldIds){
const target=root.querySelector?.('#'+CSS.escape(id));
if(!target||target.dataset.einviteEventBound==='true')continue;
target.dataset.einviteEventBound='true';
target.addEventListener('input',commitEventFieldInput);
}
}
document.addEventListener('input',commitEventFieldInput,true);
bindEventFieldInputs();
new MutationObserver(records=>{
if(records.some(record=>record.addedNodes.length))bindEventFieldInputs();
}).observe(document.documentElement,{childList:true,subtree:true});
