function copyObjectData(source,target,data,offsetIndex=0){
const stageRect=$('#stage').getBoundingClientRect();
const sourceRect=source.getBoundingClientRect();
const left=(sourceRect.left-stageRect.left)/stageRect.width*100+3+offsetIndex*1.2;
const top=(sourceRect.top-stageRect.top)/stageRect.height*100+2+offsetIndex*1.2;
target.style.left=`${Math.min(92, left)}%`;
target.style.top=`${Math.min(92, top)}%`;
target.style.width=source.style.width;
target.style.height=source.style.height;
const keys=['objectType','assetId','font','color','animation','duration','caption','alt','rotation','imageFit','imagePositionX','imagePositionY','imageMask','imageFrame','imageBrightness','imageContrast','imageSaturation','imageVibrance','imageTemperature','imageGamma','imageCurveShadows','imageCurveHighlights','imageGrayscale','imageSepia','imageBlur','imageHue','imageSharpen','imageLevelsBlack','imageLevelsWhite','imagePerspectiveX','imagePerspectiveY','imageWarpX','imageWarpY','imageMaskFeather','imageGradientMask','imageEditOperations','imageRetouchOperations','imageAdjustmentLayers','imageSmartObject','imageGeneratedPreview','imageFlipX','imageFlipY','showInHero','showInGallery','fontSize','textAlign','textVerticalAlign','textPadding','fontWeight','fontStyle','letterSpacing','lineHeight','textAutoFit','textAutoFitMax','textMinFontSize','textWrap','textColumns','textColumnGap','fillColor','shapeKind','opacity','borderWidth','borderColor','borderRadius','shadowBlur','shadowColor','backgroundEnabled','backgroundColor','backgroundOpacity','blendMode','fillMode','gradientStart','gradientEnd','gradientAngle','textGradientEnabled','textGradientStart','textGradientEnd','textGradientAngle','textStrokeWidth','textStrokeColor','textShadowBlur','textShadowColor','textTransform','animationDelay','visible','layerName','intrinsicWidth','intrinsicHeight','sizeBytes','dominantColor','responsiveBase'];
keys.forEach(key=>target.dataset[key]=source.dataset[key]??data[key]??'');
target.dataset.locked='false';
target.style.transform=`rotate(${Number(target.dataset.rotation || 0)}deg)`;
target.style.zIndex=String(nextZIndex());
if(data.type==='image'){
const img=target.querySelector('img');
img.src=data.src;
img.alt=data.alt||'Invitation image';
img.style.objectFit=data.imageFit||'cover';
img.style.objectPosition=`${data.imagePositionX ?? 50}% ${data.imagePositionY ?? 50}%`
}else{
const content=target.querySelector('.content');
setTypographyContent(content,data.html||'New text');
target.dataset.font=v19FontId(data.font);
}
applyObjectVisualStyle(target)
}
function duplicateSelection(){
const originals=currentSelection();
if(!originals.length)return;
const snapshot=capture().objects;
const newItems=[];
const groupMap=new Map();
originals.forEach((source,index)=>{
const data=snapshot[source.dataset.id];
if(!data)return;
const id=`obj-${Date.now()}-${index}`;
const duplicate=createObject(id,data.type);
$('#stage').append(duplicate);
copyObjectData(source,duplicate,data,index);
if(source.dataset.groupId){
if(!groupMap.has(source.dataset.groupId))groupMap.set(source.dataset.groupId,`group-${Date.now()}-${groupMap.size}`);
duplicate.dataset.groupId=groupMap.get(source.dataset.groupId)
}
if(data.type==='image'&&data.showInGallery!==false)state.galleryOrder=[...(state.galleryOrder||[]),id];
newItems.push(duplicate)
});
setSelection(newItems);
save()
}
