async function reconcileAssetRefs(d=state){if(!serverInvite||!d)return false;let list;try{list=await listAllAssets()}catch{return false}let iid=String(serverInvite.id),map=new Map,changed=false;for(let a of list)if(a?.serverId&&(!a.invitationId||String(a.invitationId)===iid))for(let v of[a.id,a.localAssetId,a.assetId,a.serverId,a.serverUrl,a.url])if(v)map.set(String(v),a);let walk=v=>{if(Array.isArray(v))return v.forEach(walk);if(!v||typeof v!=='object')return;for(let k of['assetId','sourceAssetId','previewAssetId','exportAssetId','resultAssetId']){let old=v[k],a=old&&(map.get(String(old))||map.get(String(v.url||v.src||'')));if(!a)continue;let id=assetIdFor(a);if(id&&String(old)!==id){if(k==='assetId'&&!v.localAssetId)v.localAssetId=String(old);v[k]=id;changed=true}if(k==='assetId'){if(!v.serverId){v.serverId=id;changed=true}if(!v.url&&a.serverUrl){v.url=a.serverUrl;changed=true}if(!v.invitationId){v.invitationId=iid;changed=true}}}Object.values(v).forEach(walk)};walk(d);return changed}
window.EInviteAssetReference={canonicalId:assetIdFor,normalizeUploaded:normalizeUploadedAsset};
async function uploadFileToServer(file){
if(!serverInvite)return null;
if(window.EInviteUpload?.upload)return window.EInviteUpload.upload(serverInvite.id,file,{name:file.name});
const response=await fetch(`/api/invitations/${serverInvite.id}/assets/raw`,{method:'POST',credentials:'same-origin',headers:{'Content-Type':file.type,'X-File-Name':encodeURIComponent(file.name)},body:file});
const payload=await response.json().catch(()=>({}));if(!response.ok)throw Error(payload.error||'Material upload failed');return payload
}
$('#photoUpload').onchange=async e=>{
let file=e.target.files[0];
if(!file)return;
if(!['image/jpeg','image/png','image/webp','image/gif'].includes(file.type))return alert('Please choose a JPEG, PNG, WebP, or GIF image.');
if(file.size>15e6)return alert('Please choose an image under 15 MB.');
try{
file=await optimizeImageFile(file);
let asset={
id:Date.now(),
name:file.name,
type:file.type,
size:file.size,
blob:file,
createdAt:new Date().toISOString()
};
if(serverInvite){
const uploaded=await uploadFileToServer(file);
Object.assign(asset,normalizeUploadedAsset(asset,uploaded))
}
await assetStore.put(asset);
await renderAssets()
}catch(error){
alert(`The material could not be stored: ${error.message||'unknown error'}`)
}
};
